-- PostgreSQL 15+; invented establishments only.
CREATE SCHEMA IF NOT EXISTS tourism_demo;
CREATE TABLE IF NOT EXISTS tourism_demo.establishments(establishment_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,establishment_ref TEXT NOT NULL UNIQUE,category TEXT NOT NULL CHECK(category IN('accommodation','tour_operator','heritage_site','activity_provider','other')),locality_code TEXT NOT NULL,display_label TEXT NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS tourism_demo.permits(permit_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,permit_ref TEXT NOT NULL UNIQUE,establishment_id BIGINT NOT NULL REFERENCES tourism_demo.establishments(establishment_id) ON DELETE RESTRICT,permit_type TEXT NOT NULL CHECK(permit_type IN('registration','operating','activity','other')),issued_on DATE,expires_on DATE,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','active','suspended','expired','closed')),source_ref TEXT NOT NULL,CHECK(expires_on IS NULL OR issued_on IS NULL OR expires_on>=issued_on));
CREATE TABLE IF NOT EXISTS tourism_demo.inspections(inspection_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,inspection_ref TEXT NOT NULL UNIQUE,establishment_id BIGINT NOT NULL REFERENCES tourism_demo.establishments(establishment_id) ON DELETE RESTRICT,inspected_at TIMESTAMPTZ NOT NULL,inspection_type TEXT NOT NULL CHECK(inspection_type IN('routine','follow_up','document_review','other')),outcome TEXT NOT NULL CHECK(outcome IN('pending','acceptable','follow_up_required','referred')),inspector_ref TEXT NOT NULL,summary TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tourism_demo.actions(action_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,action_ref TEXT NOT NULL UNIQUE,inspection_id BIGINT NOT NULL REFERENCES tourism_demo.inspections(inspection_id) ON DELETE RESTRICT,summary TEXT NOT NULL,owner_ref TEXT NOT NULL,due_date DATE,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','in_progress','blocked','closed','cancelled')),closed_at TIMESTAMPTZ,CHECK(status<>'closed' OR closed_at IS NOT NULL));
CREATE TABLE IF NOT EXISTS tourism_demo.action_events(event_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,action_id BIGINT NOT NULL REFERENCES tourism_demo.actions(action_id) ON DELETE RESTRICT,previous_status TEXT,new_status TEXT NOT NULL CHECK(new_status IN('open','in_progress','blocked','closed','cancelled')),note TEXT NOT NULL,actor_ref TEXT NOT NULL,happened_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_tourism_permit_expiry ON tourism_demo.permits(status,expires_on);
CREATE INDEX IF NOT EXISTS ix_tourism_inspection_establishment ON tourism_demo.inspections(establishment_id,inspected_at DESC);
CREATE INDEX IF NOT EXISTS ix_tourism_actions_due ON tourism_demo.actions(status,due_date) WHERE status NOT IN('closed','cancelled');
CREATE INDEX IF NOT EXISTS ix_tourism_events_action ON tourism_demo.action_events(action_id,happened_at DESC,event_id DESC);